    const parts = formatter2.formatToParts(utcGuess);
    const tzYear = parseInt(parts.find((p7) => p7.type === "year")?.value || `${year2}`, 10);
    const tzMonth = parseInt(parts.find((p7) => p7.type === "month")?.value || `${month}`, 10);
    const tzDay = parseInt(parts.find((p7) => p7.type === "day")?.value || `${day}`, 10);
    let tzHour = parseInt(parts.find((p7) => p7.type === "hour")?.value || `${hour}`, 10);
    if (tzHour === 24) tzHour = 0;
    const tzMin = parseInt(parts.find((p7) => p7.type === "minute")?.value || `${minute}`, 10);
    const tzAsUtc = Date.UTC(tzYear, tzMonth - 1, tzDay, tzHour, tzMin, 0);
    const diffMs = tzAsUtc - utcGuess.getTime();
    return new Date(utcGuess.getTime() - diffMs);
