apiRouter.post("/user/shop/purchase", async (req2, res) => {
  const userId2 = req2.userId;
  const { itemId, price, name: name3 } = req2.body;
  if (!itemId || typeof price !== "number") {
    res.status(400).json({ success: false, message: "Thi\u1EBFu th\xF4ng tin v\u1EADt ph\u1EA9m ho\u1EB7c gi\xE1 ti\u1EC1n h\u1EE3p l\u1EC7." });
    return;
  }
  try {
    const prisma = getPrisma();
    const prog = await prisma.userProgression.findUnique({ where: { userId: userId2 } });
    const currentCoins = prog?.coins ?? 0;
    if (currentCoins < price) {
      res.status(400).json({
        success: false,
        message: `B\u1EA1n kh\xF4ng \u0111\u1EE7 Coin! C\u1EA7n ${price} Coins (hi\u1EC7n c\xF3 ${currentCoins} Coins).`
      });
      return;
    }
    if (itemId !== "streak_freeze") {
      const existing = await prisma.userReward.findUnique({
        where: { userId_rewardKey: { userId: userId2, rewardKey: itemId } }
      });
      if (existing) {
        res.status(400).json({ success: false, message: "B\u1EA1n \u0111\xE3 s\u1EDF h\u1EEFu v\u1EADt ph\u1EA9m n\xE0y r\u1ED3i." });
        return;
      }
    }
    await prisma.$transaction(async (tx) => {
      await tx.userProgression.update({
        where: { userId: userId2 },
        data: { coins: { decrement: price } }
      });
      await tx.coinTransaction.create({
        data: {
          userId: userId2,
          amount: -price,
          type: "spend",
          source: "shop_purchase",
          sourceId: itemId,
          description: `\u0110\u1ED5i v\u1EADt ph\u1EA9m c\u1EEDa h\xE0ng: ${name3 || itemId}`
        }
      });
      const existingReward = await tx.userReward.findUnique({
        where: { userId_rewardKey: { userId: userId2, rewardKey: itemId } }
      });
      if (!existingReward) {
        await tx.userReward.create({
          data: {
            userId: userId2,
            rewardType: "shop_item",
            rewardKey: itemId,
            name: name3 || itemId,
            description: `V\u1EADt ph\u1EA9m m\u1EDF kh\xF3a t\u1EEB C\u1EEDa h\xE0ng N\u0103ng l\u01B0\u1EE3ng`,
            isEquipped: false
          }
        });
      }
    });
    const updatedProg = await prisma.userProgression.findUnique({ where: { userId: userId2 } });
    const allRewards = await prisma.userReward.findMany({ where: { userId: userId2 } });
    res.json({
      success: true,
      message: `\u0110\xE3 \u0111\u1ED5i th\xE0nh c\xF4ng "${name3 || itemId}"!`,
      data: {
        newCoins: updatedProg?.coins ?? 0,
        purchasedIds: allRewards.map((r8) => r8.rewardKey)
      }
    });
  } catch (err2) {
    console.error("Error purchasing shop item:", err2);
    res.status(500).json({ success: false, message: err2.message || "L\u1ED7i x\u1EED l\xFD giao d\u1ECBch mua h\xE0ng." });
  }
});
