apiRouter.get("/admin/payments/requests", requireAdmin, async (req2, res) => {
  const prisma = getPrisma();
  const { status: status2, plan, search } = req2.query;
  try {
    const whereClause = {};
    if (status2 && status2 !== "ALL") {
      if (status2 === "PENDING") whereClause.status = "PENDING";
      else if (status2 === "APPROVED") whereClause.status = { in: ["APPROVED", "Paid"] };
      else if (status2 === "REJECTED") whereClause.status = "REJECTED";
      else if (status2 === "CANCELLED") whereClause.status = "CANCELLED";
      else whereClause.status = String(status2);
    }
    if (plan && plan !== "ALL") {
      whereClause.planRequested = plan;
    }
    if (search && String(search).trim()) {
      const q4 = String(search).trim();
      whereClause.OR = [
        { customerEmail: { contains: q4, mode: "insensitive" } },
        { orderId: { contains: q4, mode: "insensitive" } },
        { txReference: { contains: q4, mode: "insensitive" } },
        { user: { name: { contains: q4, mode: "insensitive" } } }
      ];
    }
    const requests = await prisma.payment.findMany({
      where: whereClause,
      include: {
        user: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            plan: true,
            planExpiresAt: true,
            avatar: true
          }
        }
      },
      orderBy: [
        { createdAt: "desc" }
      ],
      take: 100
    });
    const [allCount, pendingCount, approvedCount, rejectedCount] = await Promise.all([
      prisma.payment.count(),
      prisma.payment.count({ where: { status: "PENDING" } }),
      prisma.payment.count({ where: { status: { in: ["APPROVED", "Paid"] } } }),
      prisma.payment.count({ where: { status: "REJECTED" } })
    ]);
    res.json({
      success: true,
      requests,
      counts: {
        all: allCount,
        pending: pendingCount,
        approved: approvedCount,
        rejected: rejectedCount
      }
    });
  } catch (err2) {
    res.status(500).json({ success: false, message: err2.message });
  }
});
