apiRouter.get("/today", async (req2, res) => {
  const userId2 = req2.userId;
  const prisma = getPrisma();
  try {
    const todayStr = (/* @__PURE__ */ new Date()).toISOString().split("T")[0];
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1e3).toISOString().split("T")[0];
    const [tasks, events2, habits, habitLogs, focusSessions, accounts, budgets] = await Promise.all([
      prisma.task.findMany({
        where: {
          userId: userId2,
          status: { notIn: ["Ho\xE0n th\xE0nh", "\u0110\xE3 xong", "H\u1EE7y"] },
          OR: [
            { dueDate: { gte: sevenDaysAgo } },
            { dueDate: null }
          ]
        },
        take: 200,
        orderBy: { dueDate: "asc" }
      }),
      prisma.calendarEvent.findMany({ where: { userId: userId2, date: todayStr } }),
      prisma.habit.findMany({ where: { userId: userId2, status: "Active" } }),
      prisma.habitLog.findMany({ where: { date: todayStr, habit: { userId: userId2 } } }),
      prisma.focusSession.findMany({ where: { userId: userId2 }, take: 10, orderBy: { createdAt: "desc" } }),
      prisma.financeAccount.findMany({ where: { userId: userId2 } }),
      prisma.budget.findMany({ where: { userId: userId2 } })
    ]);
    const habitLogMap = new Map(habitLogs.map((l4) => [l4.habitId, l4]));
    const overdueTasks = [];
    const mustDoTasks = [];
    const shouldDoTasks = [];
    const optionalTasks = [];
    const completedToday = [];
    for (const t8 of tasks) {
      if (t8.status === "Ho\xE0n th\xE0nh") {
        completedToday.push(t8);
        continue;
      }
      if (t8.dueDate && t8.dueDate < todayStr) {
        overdueTasks.push(t8);
      } else if (t8.dueDate === todayStr || t8.startDate === todayStr || !t8.dueDate) {
        if (t8.priority === "Kh\u1EA9n c\u1EA5p" || t8.priority === "Cao") {
          mustDoTasks.push(t8);
        } else if (t8.priority === "Trung b\xECnh") {
          shouldDoTasks.push(t8);
        } else {
          optionalTasks.push(t8);
        }
      }
    }
    const habitsToday = habits.map((h7) => ({
      ...h7,
      completedToday: habitLogMap.has(h7.id) && habitLogMap.get(h7.id)?.completed
    }));
    const totalBalance = accounts.reduce((sum, a10) => sum + (a10.balance || 0), 0);
    const budgetWarnings = budgets.filter((b6) => b6.limit > 0 && b6.spent >= b6.limit * 0.9);
    res.json({
      success: true,
      date: todayStr,
      summary: {
        totalTasks: tasks.length,
        overdueCount: overdueTasks.length,
        mustDoCount: mustDoTasks.length,
        todayEventsCount: events2.length,
        habitsCompletedCount: habitsToday.filter((h7) => h7.completedToday).length,
        habitsTotalCount: habitsToday.length,
        totalBalance
      },
      schedule: events2,
      tasks: {
        overdue: overdueTasks,
        mustDo: mustDoTasks,
        shouldDo: shouldDoTasks,
        optional: optionalTasks,
        completedToday
      },
      habits: habitsToday,
      budgetWarnings
    });
  } catch (err2) {
    res.status(500).json({
      success: false,
      error: { code: "TODAY_ENGINE_ERROR", message: err2.message },
      message: err2.message
    });
  }
});
