var notificationRouter = (0, import_express13.Router)();
notificationRouter.post("/dispatch", requireAuth, async (req2, res) => {
  try {
    const { recipient, subject, htmlBody, category = "GENERAL", priority = "NORMAL", metadata } = req2.body;
    if (!recipient || !subject) {
      return res.status(400).json({ success: false, message: "Thi\u1EBFu email ng\u01B0\u1EDDi nh\u1EADn ho\u1EB7c ti\xEAu \u0111\u1EC1 th\xF4ng b\xE1o" });
    }
    const prisma = getPrisma();
    const matchedUser = await prisma.user.findFirst({
      where: { email: recipient.toLowerCase().trim() },
      select: { id: true, name: true }
    });
    let notifId = null;
    if (matchedUser) {
      const createdNotif = await prisma.notification.create({
        data: {
          userId: matchedUser.id,
          title: subject,
          message: metadata?.message || subject,
          type: priority === "CRITICAL" ? "error" : priority === "HIGH" ? "warning" : "info",
          priority: priority || "NORMAL",
          category: category || "GENERAL",
          actionUrl: metadata?.actionUrl || "/?tab=dashboard",
          actionLabel: metadata?.actionLabel || "Xem tr\xEAn LifeOS",
          read: false
        }
      });
      notifId = createdNotif.id;
    }
    let queueId = null;
    if (htmlBody) {
      queueId = await emailQueueService.enqueue({
        recipient,
        subject,
        htmlBody,
        eventType: category,
        priority: priority === "CRITICAL" ? "CRITICAL" : priority === "HIGH" ? "HIGH" : "NORMAL",
        metadata: {
          notificationId: notifId,
          ...metadata
        }
      });
    }
    res.json({
      success: true,
      message: "\u0110\xE3 ti\u1EBFp nh\u1EADn v\xE0 \u0111\u01B0a th\xF4ng b\xE1o v\xE0o h\xE0ng \u0111\u1EE3i g\u1EEDi t\u1EF1 \u0111\u1ED9ng th\xE0nh c\xF4ng!",
      notificationId: notifId,
      queueId
    });
  } catch (err2) {
    console.error("[NotificationRouter] Error dispatching notification:", err2);
    res.status(500).json({ success: false, message: "L\u1ED7i m\xE1y ch\u1EE7 khi \u0111i\u1EC1u ph\u1ED1i th\xF4ng b\xE1o: " + err2.message });
  }
});
