notificationRouter.post("/email-config", requireAuth, async (req2, res) => {
  try {
    const userRole = req2.user?.role || "";
    const isAdmin = userRole === "ADMIN" || userRole === "SUPERADMIN";
    if (!isAdmin) {
      return res.status(403).json({ success: false, message: "B\u1EA1n kh\xF4ng c\xF3 quy\u1EC1n thay \u0111\u1ED5i c\u1EA5u h\xECnh g\u1EEDi email h\u1EC7 th\u1ED1ng" });
    }
    const {
      enabled,
      serviceType,
      webhookUrl,
      emailjsServiceId,
      emailjsTemplateId,
      emailjsPublicKey,
      emailjsPrivateKey,
      user,
      appPassword,
      fromName,
      fromEmail
    } = req2.body;
    const currentConfig = await gmailService.getConfig();
    const updatedConfig = {
      ...currentConfig,
      enabled: Boolean(enabled),
      serviceType: serviceType || currentConfig.serviceType || "webhook",
      webhookUrl: webhookUrl !== void 0 ? webhookUrl.trim() : currentConfig.webhookUrl,
      emailjsServiceId: emailjsServiceId !== void 0 ? emailjsServiceId.trim() : currentConfig.emailjsServiceId,
      emailjsTemplateId: emailjsTemplateId !== void 0 ? emailjsTemplateId.trim() : currentConfig.emailjsTemplateId,
      emailjsPublicKey: emailjsPublicKey !== void 0 ? emailjsPublicKey.trim() : currentConfig.emailjsPublicKey,
      user: user !== void 0 ? user.trim() : currentConfig.user,
      fromName: fromName !== void 0 ? fromName.trim() : currentConfig.fromName,
      fromEmail: fromEmail !== void 0 ? fromEmail.trim() : currentConfig.fromEmail
    };
    if (emailjsPrivateKey) {
      updatedConfig.emailjsPrivateKey = emailjsPrivateKey.trim();
    }
    if (appPassword && appPassword.trim().length > 0) {
      updatedConfig.appPassword = appPassword.trim();
    }
    await gmailService.saveConfig(updatedConfig, req2.user?.userId);
    res.json({
      success: true,
      message: "C\u1EADp nh\u1EADt c\u1EA5u h\xECnh g\u1EEDi email t\u1EF1 \u0111\u1ED9ng th\xE0nh c\xF4ng!",
      config: {
        enabled: updatedConfig.enabled,
        serviceType: updatedConfig.serviceType,
        webhookUrl: updatedConfig.webhookUrl,
        user: updatedConfig.user,
        fromName: updatedConfig.fromName
      }
    });
  } catch (err2) {
    res.status(500).json({ success: false, message: err2.message });
  }
});
